import scales = require( './index' );


// TESTS //

// The function returns an array of strings when not provided any arguments...
{
	scales(); // $ExpectType string[]
}

// The function returns an array of strings when provided a recognized scale kind...
{
	scales( 'all' ); // $ExpectType string[]
	scales( 'quantitative' ); // $ExpectType string[]
	scales( 'discrete' ); // $ExpectType string[]
	scales( 'discretizing' ); // $ExpectType string[]
}

// The compiler throws an error if the function is provided an invalid first argument...
{
	scales( 5 ); // $ExpectError
	scales( true ); // $ExpectError
	scales( false ); // $ExpectError
	scales( null ); // $ExpectError
	scales( [] ); // $ExpectError
	scales( {} ); // $ExpectError
	scales( ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	scales( 'quantitative', {} ); // $ExpectError
}
